#include "nvs_manager.hpp"
#include "esp_log.h"
#include <vector>

// Logging tag used to identify console outputs generated by NvsManager
static const char* TAG = "NvsManager";

// Constructor: Initializes class fields to default state prior to hardware initialization
NvsManager::NvsManager() : m_namespace_name("storage"), m_partition_label(NVS_DEFAULT_PART_NAME), m_nvs_handle(0), m_is_initialized(false) {}

// Destructor: Guarantees active handles are closed during object lifecycle cleanup
NvsManager::~NvsManager() {
    if (m_is_initialized) {
        deinit(); // Cleanly close NVS handle on destruction
    }
}

// Truncates keys to 15 characters to satisfy ESP32 NVS key length limits
std::string NvsManager::sanitizeKey(const std::string& key) const {
    if (key.length() > 15) { // NVS keys are strictly limited to 15 characters (excluding null terminator)
        ESP_LOGW(TAG, "Key '%s' exceeds 15 char limit, truncating to '%s'", key.c_str(), key.substr(0, 15).c_str());
        return key.substr(0, 15); // Return truncated key string
    }
    return key; // Return valid key as-is
}

// Initializes the NVS flash default partition and opens a read-write namespace handle
esp_err_t NvsManager::init(const std::string& namespace_name, const std::string& partition_label) {
    m_namespace_name = namespace_name;     // Store requested NVS namespace name
    m_partition_label = partition_label;   // Store target NVS partition label name

    ESP_LOGI(TAG, "Initializing NVS partition [%s] with namespace [%s]", m_partition_label.c_str(), m_namespace_name.c_str());

    // Attempt to initialize default NVS partition hardware driver
    esp_err_t ret = nvs_flash_init_partition(m_partition_label.c_str());

    // Handle initial flash error cases (e.g., no free pages or new partition layout)
    if (ret == ESP_ERR_NVS_NO_FREE_PAGES || ret == ESP_ERR_NVS_NEW_VERSION_FOUND) {
        ESP_LOGW(TAG, "NVS partition truncated or corrupted, erasing and retrying...");
        ESP_ERROR_CHECK(nvs_flash_erase_partition(m_partition_label.c_str())); // Erase corrupted flash storage
        ret = nvs_flash_init_partition(m_partition_label.c_str());             // Re-initialize driver after erase
    }

    if (ret != ESP_OK) { // Check if NVS driver initialization failed
        ESP_LOGE(TAG, "Failed to initialize NVS flash: %s", esp_err_to_name(ret));
        return ret; // Early return with error code
    }

    // Open read-write handle to the requested NVS namespace
    ret = nvs_open_from_partition(m_partition_label.c_str(), m_namespace_name.c_str(), NVS_READWRITE, &m_nvs_handle);
    if (ret != ESP_OK) { // Check if namespace failed to open
        ESP_LOGE(TAG, "Failed to open NVS namespace '%s': %s", m_namespace_name.c_str(), esp_err_to_name(ret));
        return ret; // Return error on failure
    }

    m_is_initialized = true; // Mark component state as ready
    size_t total = 0, free_entries = 0;
    
    // Log capacity statistics upon success
    if (getStorageStats(&total, &free_entries)) {
        ESP_LOGI(TAG, "NVS Initialized. Total Entries: %u, Free Entries: %u", total, free_entries);
    }

    return ESP_OK; // Return success status code
}

// Closes NVS handle and unregisters initialized partition resources
esp_err_t NvsManager::deinit() {
    if (!m_is_initialized) return ESP_OK; // Ignore if already uninitialized

    if (m_nvs_handle != 0) {
        nvs_close(m_nvs_handle); // Close active open handle
        m_nvs_handle = 0;        // Reset handle variable
    }

    m_is_initialized = false;    // Update initialization state flag
    ESP_LOGI(TAG, "NVS handle closed successfully");
    return ESP_OK;
}

// Stores string value into NVS key and commits changes to flash
bool NvsManager::writeFile(const std::string& key, const std::string& value) {
    if (!m_is_initialized) return false; // Verify module readiness
    
    std::string safe_key = sanitizeKey(key); // Format key to valid length

    // Set string entry in open NVS handle
    esp_err_t ret = nvs_set_str(m_nvs_handle, safe_key.c_str(), value.c_str());
    if (ret != ESP_OK) { // Log error if set operation fails
        ESP_LOGE(TAG, "Failed to write key '%s': %s", safe_key.c_str(), esp_err_to_name(ret));
        return false;
    }

    // Commit written changes from RAM cache down to physical NVS flash storage
    ret = nvs_commit(m_nvs_handle);
    if (ret != ESP_OK) { // Check commit return status
        ESP_LOGE(TAG, "Failed to commit key '%s': %s", safe_key.c_str(), esp_err_to_name(ret));
        return false;
    }

    return true; // Return success on successful commit
}

// Appends data to an existing NVS string entry
bool NvsManager::appendFile(const std::string& key, const std::string& data) {
    if (!m_is_initialized) return false; // Fail early if not initialized

    std::string current_value = readFile(key); // Fetch current key value string (or empty if nonexistent)
    current_value += data;                    // Concatenate target append data

    return writeFile(key, current_value);    // Overwrite updated string back to key
}

