std::string NvsManager::readFile(const std::string& key) {
    if (!m_is_initialized) return ""; // Fail-safe return on uninitialized state

    std::string safe_key = sanitizeKey(key); // Pre-process input key
    size_t required_size = 0;

    // Fetch required buffer allocation size for stored string length (including null terminator)
    esp_err_t ret = nvs_get_str(m_nvs_handle, safe_key.c_str(), NULL, &required_size);
    if (ret != ESP_OK || required_size == 0) { // Handle missing key or read failure gracefully
        ESP_LOGW(TAG, "Key '%s' not found or failed to read: %s", safe_key.c_str(), esp_err_to_name(ret));
        return ""; // Return empty string if key does not exist
    }

    // [MODIFIED FOR SAFETY]: Replaced direct std::string buffer manipulation with a std::vector<char> 
    // buffer to safely follow the ESP-IDF two-step query pattern and avoid undefined behavior with internal string pointers.
    std::vector<char> buffer(required_size);
    size_t buffer_len = required_size; // Track available length per ESP-IDF API spec

    // Retrieve string content into target pre-allocated memory buffer
    ret = nvs_get_str(m_nvs_handle, safe_key.c_str(), buffer.data(), &buffer_len);
    if (ret != ESP_OK) { // Check second step read operation result
        ESP_LOGE(TAG, "Failed to read string data for key '%s': %s", safe_key.c_str(), esp_err_to_name(ret));
        return "";
    }

    // Return retrieved data payload, safely constructing std::string from the null-terminated buffer
    return std::string(buffer.data());
}
// Deletes key entry from the open NVS namespace
bool NvsManager::deleteFile(const std::string& key) {
    if (!m_is_initialized) return false; // Verify module state

    std::string safe_key = sanitizeKey(key); // Sanitize key length

    // Erase key entry from open namespace
    esp_err_t ret = nvs_erase_key(m_nvs_handle, safe_key.c_str());
    if (ret != ESP_OK) { // Check if erase failed
        ESP_LOGE(TAG, "Failed to erase key '%s': %s", safe_key.c_str(), esp_err_to_name(ret));
        return false;
    }

    // Flush change to physical storage
    ret = nvs_commit(m_nvs_handle);
    return (ret == ESP_OK); // Return true if commit succeeds
}

// Checks if a key exists in current NVS namespace
bool NvsManager::exists(const std::string& key) {
    if (!m_is_initialized) return false; // Fail fast if uninitialized

    std::string safe_key = sanitizeKey(key); // Sanitize input key
    size_t required_size = 0;

    // Attempt to query string size without allocating memory buffer
    esp_err_t ret = nvs_get_str(m_nvs_handle, safe_key.c_str(), NULL, &required_size);
    return (ret == ESP_OK); // Returns true if key exists, false otherwise
}

// Queries available and used entry statistics for the active NVS partition
bool NvsManager::getStorageStats(size_t* total_entries, size_t* free_entries) {
    if (!m_is_initialized) return false; // Fail fast if module uninitialized

    nvs_stats_t nvs_stats;
    // Query statistics from lower-level ESP-IDF NVS driver
    esp_err_t ret = nvs_get_stats(m_partition_label.c_str(), &nvs_stats);
    if (ret == ESP_OK) {
        *total_entries = nvs_stats.total_entries; // Output total available entries metric
        *free_entries = nvs_stats.free_entries;   // Output free entries metric
        return true; // Return operation status success
    }

    return false; // Return failure status
}